const T=window.THREE;
export function createCelebration(scene){const c=document.createElement('canvas');c.width=c.height=32;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(16,16,1,16,16,15);g.addColorStop(0,'#fff7de');g.addColorStop(.2,'#fff7deaa');g.addColorStop(1,'#fff7de00');ctx.fillStyle=g;ctx.fillRect(0,0,32,32);const tex=new T.CanvasTexture(c),geometry=new T.BufferGeometry(),positions=new Float32Array(48*3);for(let i=0;i<48;i++){positions[i*3]=Math.sin(i*2.4)*1.1;positions[i*3+1]=1.8+(i%12)*.19;positions[i*3+2]=.4+Math.cos(i*1.7)*.4;}geometry.setAttribute('position',new T.BufferAttribute(positions,3));const material=new T.PointsMaterial({color:0xffe4a6,size:.025,map:tex,transparent:true,depthWrite:false,blending:T.AdditiveBlending});const points=new T.Points(geometry,material);points.visible=false;scene.add(points);return{points,update(t,enabled){points.visible=enabled;points.rotation.y=t*.07;material.opacity=.55+.15*Math.sin(t);},dispose(){geometry.dispose();material.dispose();tex.dispose();scene.remove(points);}};}
